package com.hssa.auth.entity; import jakarta.persistence.*; import lombok.AllArgsConstructor; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter; import org.hibernate.annotations.CreationTimestamp; import java.time.LocalDateTime; import java.util.UUID; @Entity @Table(name = "password_reset_tokens", schema = "auth") @Getter @Setter @NoArgsConstructor @AllArgsConstructor public class PasswordResetToken { @Id @GeneratedValue(strategy = GenerationType.UUID) @Column(name = "id", updatable = false, nullable = false) private UUID id; @ManyToOne(fetch = FetchType.LAZY) @JoinColumn(name = "user_id", nullable = false) private User user; @Column(name = "token", nullable = false, unique = true) private String token; @Column(name = "expires_at", nullable = false) private LocalDateTime expiresAt; @Column(name = "used_at") private LocalDateTime usedAt; @CreationTimestamp @Column(name = "created_at", nullable = false, updatable = false) private LocalDateTime createdAt; }
